-- Pure validators (identity 5.1): they read no table, and a CHECK runs with the writer's privileges, so PUBLIC runs them.
-- Array of strings: count in [min_n, max_n], every element a string whose trimmed length is in [min_len, max_len].
CREATE FUNCTION jsonb_text_array_ok(a jsonb, min_n int, max_n int, min_len int, max_len int) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
SELECT CASE WHEN jsonb_typeof(a) = 'array'
  THEN jsonb_array_length(a) BETWEEN min_n AND max_n
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(a) e
                        WHERE jsonb_typeof(e) <> 'string'
                           OR char_length(btrim(e #>> '{}')) NOT BETWEEN min_len AND max_len)
  ELSE false END
$$;--> statement-breakpoint
-- A JSON number that is a whole number inside [lo, hi]. CASE guarantees the cast only runs on digit strings.
CREATE FUNCTION jsonb_int_between(v jsonb, lo int, hi int) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
SELECT CASE WHEN jsonb_typeof(v) = 'number' AND (v #>> '{}') ~ '^[0-9]{1,9}$'
            THEN (v #>> '{}')::int BETWEEN lo AND hi ELSE false END
$$;--> statement-breakpoint
-- Mirror of preferencesSchema in shared/src/schemas.ts. Unknown extra keys are tolerated (zod strips them before the write).
CREATE FUNCTION preferences_valid(p jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
BEGIN
  IF p IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  IF NOT jsonb_text_array_ok(p -> 'roles', 1, 10, 2, 80) THEN RETURN false; END IF;
  IF NOT jsonb_text_array_ok(p -> 'locations', 0, 20, 2, 80) THEN RETURN false; END IF;
  IF NOT jsonb_text_array_ok(p -> 'excludedCompanies', 0, 200, 1, 120) THEN RETURN false; END IF;
  IF NOT jsonb_text_array_ok(p -> 'excludedKeywords', 0, 100, 1, 60) THEN RETURN false; END IF;
  IF NOT jsonb_text_array_ok(p -> 'seniority', 1, 5, 1, 20) THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p -> 'seniority') s
              WHERE s NOT IN ('intern','entry','mid','senior','lead')) THEN RETURN false; END IF;
  IF jsonb_typeof(p -> 'remoteOk') IS DISTINCT FROM 'boolean' THEN RETURN false; END IF;
  IF coalesce(p ->> 'workAuthorization', '') NOT IN
       ('citizen_or_pr','needs_sponsorship_now','needs_sponsorship_later','opt_stem_opt') THEN RETURN false; END IF;
  IF NOT (jsonb_typeof(p -> 'salaryFloorUsd') = 'null' OR jsonb_int_between(p -> 'salaryFloorUsd', 0, 1000000)) THEN RETURN false; END IF;
  IF NOT jsonb_int_between(p -> 'fitThreshold', 50, 95) THEN RETURN false; END IF;
  IF NOT jsonb_int_between(p -> 'maxApplicationsPerCompanyPer30Days', 1, 5) THEN RETURN false; END IF;
  RETURN true;
END $$;--> statement-breakpoint
CREATE FUNCTION onboarding_rank(s text) RETURNS int
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
SELECT CASE s WHEN 'resume' THEN 0 WHEN 'confirm-facts' THEN 1 WHEN 'done' THEN 2 END
$$;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION jsonb_text_array_ok(jsonb, int, int, int, int), jsonb_int_between(jsonb, int, int),
  preferences_valid(jsonb), onboarding_rank(text) TO PUBLIC;--> statement-breakpoint

ALTER TABLE "profiles" ADD CONSTRAINT "profiles_forwarding_address_ck" CHECK (forwarding_address = lower(forwarding_address) AND forwarding_address ~ '^[a-z0-9._+-]+@[a-z0-9.-]+\.[a-z]{2,}$') NOT VALID;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_forwarding_state_ck" CHECK (forwarding_state IN ('not_started','awaiting_verification','verified_pending_first_mail','active','stale'));--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_lengths_ck" CHECK (char_length(phone) <= 40 AND char_length(city) <= 120 AND char_length(country) <= 120) NOT VALID;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_urls_ck" CHECK (linkedin_url ~* '^https?://[^[:space:]]+$' AND char_length(linkedin_url) <= 300
        AND github_url ~* '^https?://[^[:space:]]+$' AND char_length(github_url) <= 300
        AND portfolio_url ~* '^https?://[^[:space:]]+$' AND char_length(portfolio_url) <= 300) NOT VALID;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_email_hash_ck" CHECK (normalized_email_hash ~ '^[0-9a-f]{64}$');--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_sensitive_enc_ck" CHECK (octet_length(sensitive_answers_enc) BETWEEN 29 AND 16384);--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_preferences_ck" CHECK (preferences IS NULL OR preferences_valid(preferences)) NOT VALID;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_versions_ck" CHECK (preferences_version >= 0 AND facts_version >= 0);--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_mail_opt_out_ck" CHECK (mail_opt_out <@ ARRAY['digest','outcome_report','autopilot_summary','reminders']::text[] AND cardinality(mail_opt_out) <= 4);--> statement-breakpoint

-- profiles_guard (identity 5.4): the key and the forwarding address (the only inbound-mail key, INV-6) never change but
-- by an operator; onboarding only moves forward (silently: the parser sets 'confirm-facts' after every parse); a time
-- zone must exist; preferences_version counts real preference changes and facts_version never goes back.
-- ponytail: facts_version stays 0 until the facts_bump_* statement triggers land with facts_snapshot_hash (database-38).
CREATE FUNCTION profiles_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.user_id <> OLD.user_id THEN
    RAISE EXCEPTION 'profiles.user_id is immutable' USING ERRCODE = '23514', CONSTRAINT = 'profiles_user_immutable';
  END IF;
  IF NEW.forwarding_address IS DISTINCT FROM OLD.forwarding_address AND kairos_actor() <> 'ops' THEN
    RAISE EXCEPTION 'forwarding_address is immutable' USING ERRCODE = '23514', CONSTRAINT = 'profiles_forwarding_address_immutable';
  END IF;
  IF onboarding_rank(NEW.onboarding_step) < onboarding_rank(OLD.onboarding_step) THEN
    NEW.onboarding_step := OLD.onboarding_step;
  END IF;
  IF NEW.timezone IS DISTINCT FROM OLD.timezone
     AND NOT EXISTS (SELECT 1 FROM pg_timezone_names z WHERE z.name = NEW.timezone) THEN
    RAISE EXCEPTION 'unknown time zone %', NEW.timezone USING ERRCODE = '22023';
  END IF;
  IF NEW.preferences IS DISTINCT FROM OLD.preferences THEN
    NEW.preferences_version := OLD.preferences_version + 1;
  ELSE
    NEW.preferences_version := OLD.preferences_version;
  END IF;
  IF NEW.facts_version < OLD.facts_version AND kairos_actor() <> 'ops' THEN
    NEW.facts_version := OLD.facts_version;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER profiles_guard_bu BEFORE UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION profiles_guard();--> statement-breakpoint

-- assert_same_owner (identity 5.2): a reference to another tenant's row can only come from a bug; it fails closed. Runs
-- only when the reference or the owner changes, so the SET NULL actions cost nothing.
CREATE FUNCTION assert_same_owner() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ref uuid; owner text; unchanged boolean;
BEGIN
  EXECUTE format('SELECT ($1).%I', TG_ARGV[1]) INTO ref USING NEW;
  IF ref IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' THEN
    EXECUTE format('SELECT ($1).%1$I IS NOT DISTINCT FROM ($2).%1$I AND ($1).user_id = ($2).user_id', TG_ARGV[1])
      INTO unchanged USING NEW, OLD;
    IF unchanged THEN RETURN NEW; END IF;
  END IF;
  EXECUTE format('SELECT user_id FROM %I WHERE id = $1', TG_ARGV[0]) INTO owner USING ref;
  IF owner IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'cross-tenant reference: %.% points at a row owned by another user', TG_TABLE_NAME, TG_ARGV[1]
      USING ERRCODE = '23514', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER facts_owner_profile BEFORE INSERT OR UPDATE OF user_id, resume_profile_id ON facts
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('resume_profiles', 'resume_profile_id');--> statement-breakpoint
CREATE TRIGGER resumes_owner_profile BEFORE INSERT OR UPDATE OF user_id, resume_profile_id ON resumes
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('resume_profiles', 'resume_profile_id');--> statement-breakpoint

-- applications_assert_owner (_db/applications.md 5.2): the match and the resume profile belong to the application's
-- owner. The resume_base_revision_id rule joins with that column (WP-42).
CREATE FUNCTION applications_assert_owner() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.match_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.match_id IS DISTINCT FROM OLD.match_id OR NEW.user_id <> OLD.user_id)
     AND NOT EXISTS (SELECT 1 FROM matches m WHERE m.id = NEW.match_id AND m.user_id = NEW.user_id) THEN
    RAISE EXCEPTION 'match does not belong to the application owner' USING ERRCODE = '23514', CONSTRAINT = 'applications_assert_owner';
  END IF;
  IF NEW.resume_profile_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.resume_profile_id IS DISTINCT FROM OLD.resume_profile_id OR NEW.user_id <> OLD.user_id)
     AND NOT EXISTS (SELECT 1 FROM resume_profiles p WHERE p.id = NEW.resume_profile_id AND p.user_id = NEW.user_id) THEN
    RAISE EXCEPTION 'resume profile does not belong to the application owner' USING ERRCODE = '23514', CONSTRAINT = 'applications_assert_owner';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER applications_assert_owner_biu BEFORE INSERT OR UPDATE OF user_id, match_id, resume_profile_id ON applications
  FOR EACH ROW EXECUTE FUNCTION applications_assert_owner();
